open! Core
open! Desmos_compiler
open! Languages
open! Types

let print_pastable_javascript prog =
  let compiled_prog =
    prog |> Example_programs.compile_to_vm
    |> Pass_generate_desmos_output.compile
  in
  compiled_prog |> Desmos_output.to_pastable_javascript |> print_endline

